#!/usr/bin/env node
/**
 * CARUP-UX-REBUILD-01 · RX-02A S1-1 — token generator.
 *
 * Single source: shared/tokens/tokens.json (the machine-checkable token contract).
 * Outputs (generated — do not edit by hand):
 *   web/src/styles/tokens.css   — CSS custom properties (light authority + inert dark-body scope)
 *   web/tailwind.tokens.js      — Tailwind theme extension consumed by web/tailwind.config.js
 *
 * Usage:
 *   node scripts/build-tokens.mjs            build both outputs
 *   node scripts/build-tokens.mjs --check    regenerate in-memory; fail if on-disk outputs drift
 *
 * Imported as a module by scripts/tests/tokens.test.mjs (parity + WCAG + mutation tests).
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const TOKENS_PATH = path.join(ROOT, 'shared/tokens/tokens.json')
const CSS_OUT = path.join(ROOT, 'web/src/styles/tokens.css')
const TW_OUT = path.join(ROOT, 'web/tailwind.tokens.js')

export function loadTokens(p = TOKENS_PATH) {
  return JSON.parse(readFileSync(p, 'utf8'))
}

/** Resolve a token value: names like "paper"/"action" resolve through `raw`; "#hex" and "rgba(...)" pass through. */
export function resolveValue(raw, v) {
  if (typeof v !== 'string') return v
  if (v.startsWith('#') || v.startsWith('rgba') || v.startsWith('0.')) return v
  if (v in raw) return raw[v]
  throw new Error(`unresolved token reference: ${v}`)
}

export function hexToRgb(hex) {
  const h = hex.replace('#', '')
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16))
}

function rgbToHex([r, g, b]) {
  return '#' + [r, g, b].map((x) => Math.round(x).toString(16).padStart(2, '0')).join('').toUpperCase()
}

/** "#RRGGBB" -> "H S% L%" triplet for the shadcn hsl(var(--slot)) convention (slash alpha preserved). */
export function hexToHslTriplet(hex) {
  const [r, g, b] = hexToRgb(hex).map((x) => x / 255)
  const max = Math.max(r, g, b), min = Math.min(r, g, b)
  const l = (max + min) / 2
  if (max === min) return `0 0% ${(l * 100).toFixed(1)}%`
  const d = max - min
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min)
  let h
  switch (max) {
    case r: h = ((g - b) / d + (g < b ? 6 : 0)) / 6; break
    case g: h = ((b - r) / d + 2) / 6; break
    default: h = ((r - g) / d + 4) / 6
  }
  return `${Math.round(h * 360)} ${(s * 100).toFixed(1)}% ${(l * 100).toFixed(1)}%`
}

function rgbaToParts(rgba) {
  const m = rgba.match(/^rgba\((\d+),(\d+),(\d+),([\d.]+)\)$/)
  if (!m) throw new Error(`not an rgba() value: ${rgba}`)
  return { r: +m[1], g: +m[2], b: +m[3], a: +m[4] }
}

/** Alpha-composite an rgba tint onto an opaque base -> opaque hex (S0 methodology). */
export function composite(baseHex, rgba) {
  const base = hexToRgb(baseHex)
  const { r, g, b, a } = rgbaToParts(rgba)
  return rgbToHex([a * r + (1 - a) * base[0], a * g + (1 - a) * base[1], a * b + (1 - a) * base[2]])
}

export function buildArtifacts(tokens) {
  const raw = tokens.raw
  const sem = Object.fromEntries(Object.entries(tokens.semantic.light).map(([k, v]) => [k, resolveValue(raw, v)]))
  const darkBase = tokens.darkSoftBase
  const L = []
  const push = (s = '') => L.push(s)

  push('/* AUTO-GENERATED by scripts/build-tokens.mjs from shared/tokens/tokens.json — do not edit by hand. */')
  push('/* Source of truth: ' + tokens.meta.contract + ' */')
  push(':root {')
  push('  /* ── raw primitives ── */')
  for (const [k, v] of Object.entries(raw)) push(`  --carup-raw-${k}: ${v};`)
  push('')
  push('  /* ── semantic · light (runtime contract) ── */')
  for (const [k, v] of Object.entries(sem)) push(`  --carup-${k}: ${v};`)
  push('')
  push('  /* ── status registry · light ── */')
  for (const [name, s] of Object.entries(tokens.status)) {
    push(`  --carup-${name}: ${resolveValue(raw, s.lightInk)};`)
    push(`  --carup-${name}-soft: ${resolveValue(raw, s.lightSoft)};`)
  }
  push('')
  push('  /* ── status registry · dark body (INERT until D-07; scope below carries the overrides) ── */')
  push(`  --carup-dark-soft-base: ${darkBase};`)
  for (const [name, s] of Object.entries(tokens.status)) {
    push(`  --carup-${name}-dark: ${resolveValue(raw, s.darkInk)};`)
    push(`  --carup-${name}-soft-dark: ${s.darkSoftRgba}; /* over ${darkBase} */`)
    push(`  --carup-${name}-soft-dark-composited: ${composite(darkBase, s.darkSoftRgba)};`)
  }
  push('')
  push('  /* ── structure ── */')
  tokens.spacing.forEach((px, i) => push(`  --carup-space-${i + 1}: ${px}px;`))
  for (const [k, v] of Object.entries(tokens.radius)) push(`  --carup-radius-${k}: ${v}px;`)
  push(`  --carup-font-sans: ${tokens.fonts.sans.stack};`)
  push(`  --carup-font-mono: ${tokens.fonts.mono.stack};`)
  push(`  --carup-content-width-public: ${tokens.contentWidths.public}px;`)
  push(`  --carup-content-width-workspace: ${tokens.contentWidths.workspace}px;`)
  push(`  --carup-content-width-focused: ${tokens.contentWidths.focused}px;`)
  push(`  --carup-shadow-sheet: ${tokens.elevation.stickyCtaAndSheets};`)
  push('  --carup-focus-ring-width: 2px;')
  push('  --carup-focus-ring-offset: 1px;')
  push('')
  push('  /* ── shadcn semantic slots (repinned to the contract; consumed as hsl(var(--slot))) ── */')
  for (const [k, v] of Object.entries(tokens.shadcnSlots.light)) {
    if (k.startsWith('_')) continue
    if (k === 'radius') { push(`  --radius: ${v};`); continue }
    const resolved = resolveValue(raw, v)
    push(`  --${k}: ${resolved.startsWith('rgba') ? `0 0% 100% / ${rgbaToParts(resolved).a}` : hexToHslTriplet(resolved)};`)
  }
  push('}')
  push('')
  push('/* Dark body variant — token-complete per contract §1.4(3) but INERT: no runtime toggle ships')
  push('   until the Owner signs off D-07 (dark action-orange swatch). Scope is unreferenced by app code. */')
  push('.carup-theme-dark-body {')
  for (const [k, v] of Object.entries(tokens.semantic.darkBody)) {
    if (k.startsWith('_')) continue
    push(`  --carup-${k}: ${v};`)
  }
  push('}')
  push('')
  const css = L.join('\n')

  const tw = []
  tw.push('/** AUTO-GENERATED by scripts/build-tokens.mjs from shared/tokens/tokens.json — do not edit by hand. */')
  tw.push('module.exports = {')
  tw.push('  colors: {')
  tw.push('    carup: {')
  tw.push('      // raw primitives (palette) — reference via e.g. text-carup-raw-action')
  tw.push('      raw: {')
  for (const [k, v] of Object.entries(raw)) tw.push(`        '${k}': 'var(--carup-raw-${k})',`)
  tw.push('      },')
  for (const [k] of Object.entries(sem)) tw.push(`      '${k.replace('color-', '')}': 'var(--carup-${k})',`)
  tw.push('    },')
  tw.push('    status: {')
  for (const name of Object.keys(tokens.status)) {
    tw.push(`      '${name}': 'var(--carup-${name})',`)
    tw.push(`      '${name}-soft': 'var(--carup-${name}-soft)',`)
  }
  tw.push('    },')
  tw.push('  },')
  tw.push('  fontFamily: {')
  tw.push(`    sans: [${tokens.fonts.sans.stack.split(', ').map((s) => `'${s.replace(/'/g, '')}'`).join(', ')}],`)
  tw.push(`    mono: [${tokens.fonts.mono.stack.split(', ').map((s) => `'${s.replace(/'/g, '')}'`).join(', ')}],`)
  tw.push('  },')
  tw.push('  borderRadius: { chrome: \'2px\', control: \'6px\', card: \'12px\' },')
  tw.push('  boxShadow: { sheet: \'var(--carup-shadow-sheet)\' },')
  tw.push('}')
  tw.push('')
  return { css, tailwind: tw.join('\n') }
}

function writeOutputs({ css, tailwind }) {
  mkdirSync(path.dirname(CSS_OUT), { recursive: true })
  writeFileSync(CSS_OUT, css)
  writeFileSync(TW_OUT, tailwind)
  console.log(`[tokens] wrote ${path.relative(ROOT, CSS_OUT)} (${css.length} bytes)`)
  console.log(`[tokens] wrote ${path.relative(ROOT, TW_OUT)} (${tailwind.length} bytes)`)
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const artifacts = buildArtifacts(loadTokens())
  if (process.argv.includes('--check')) {
    const cssDrift = readFileSync(CSS_OUT, 'utf8') !== artifacts.css
    const twDrift = readFileSync(TW_OUT, 'utf8') !== artifacts.tailwind
    if (cssDrift || twDrift) {
      console.error('[tokens] DRIFT: generated outputs differ from shared/tokens/tokens.json. Run `npm run tokens:build`.')
      process.exit(1)
    }
    console.log('[tokens] check OK — outputs match the token source.')
  } else {
    writeOutputs(artifacts)
  }
}
